import React, { useState, useEffect } from 'react';
import axiosInstance from 'axios';

export default function TeacherQuiz({ userName, subject, qualifications, teacherGrades, timetable }) {
  const [quizzes, setQuizzes] = useState([]);
  const [masterBank, setMasterBank] = useState([]);
  
  // 🟢 RELATIONAL DATABASE STATES
  const [teachersList, setTeachersList] = useState([]);
  const [subjectsList, setSubjectsList] = useState([]);
  const [timetableRows, setTimetableRows] = useState([]);
  
  const [activeSubject, setActiveSubject] = useState('');
  const [formPaperGrade, setFormPaperGrade] = useState('');
  const [selectedQuizId, setSelectedQuizId] = useState('');
  const [quizTitle, setQuizTitle] = useState('');
  
  // Form States for Questions
  const [editingId, setEditingId] = useState(null);
  const [qText, setQText] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');
  const [correctOpt, setCorrectOpt] = useState('A');
  const [qMarks, setQMarks] = useState(2);

  // 🟢 1. ඩේටාබේස් එකේ සියලුම ටේබල්ස් ලයිව්ම ලෝඩ් කරගැනීම
  const refreshData = () => {
    // 💾 Teachers ටේබල් එක ලෝඩ් කිරීම
    axiosInstance.get('http://localhost:8081/api/teachers')
      .then(res => setTeachersList(Array.isArray(res.data) ? res.data : []))
      .catch(() => setTeachersList([
        { id: 1, teacher_code: 'TC_001', full_name: 'Charaka Dikwella' },
        { id: 2, teacher_code: 'TC_002', full_name: 'Buddhika Darshani' },
        { id: 3, teacher_code: 'TC_003', full_name: 'Ravindu Jayaweera' }
      ]));

    // 💾 Subjects ටේබල් එක ලෝඩ් කිරීම
    axiosInstance.get('http://localhost:8081/api/subjects')
      .then(res => setSubjectsList(Array.isArray(res.data) ? res.data : []))
      .catch(() => setSubjectsList([
        { id: 1, subject_code: 'Sub_001', subject_name: 'Mathematics' },
        { id: 2, subject_code: 'Sub_002', subject_name: 'Science' },
        { id: 5, subject_code: 'Sub_005', subject_name: 'ICT' }
      ]));

    // 💾 Timetable ටේබල් එක ලෝඩ් කිරීම (ඔයා එවපු ස්ක්‍රීන්ෂොට් එකේ ඩේටා මීටර් කර ඇත)
    axiosInstance.get('http://localhost:8081/api/timetable')
      .then(res => setTimetableRows(Array.isArray(res.data) ? res.data : []))
      .catch(() => setTimetableRows([
        { id: 1, grade: 'Grade 9', subject_code: 'Sub_001', teacher_code: 'TC_001' },
        { id: 2, grade: 'Grade 10', subject_code: 'Sub_001', teacher_code: 'TC_001' },
        { id: 4, grade: 'Grade 6', subject_code: 'Sub_001', teacher_code: 'TC_002' },
        { id: 5, grade: 'Grade 7', subject_code: 'Sub_001', teacher_code: 'TC_002' },
        { id: 6, grade: 'Grade 8', subject_code: 'Sub_001', teacher_code: 'TC_002' },
        { id: 7, grade: 'Grade 6', subject_code: 'Sub_002', teacher_code: 'TC_003' }
      ]));

    // Quizzes සහ Question Bank ලෝඩ් කිරීම
    axiosInstance.get('http://localhost:8081/api/quizzes')
      .then(res => setQuizzes(Array.isArray(res.data) ? res.data : []))
      .catch(() => setQuizzes(JSON.parse(localStorage.getItem('aura_math_quizzes')) || []));
    
    axiosInstance.get('http://localhost:8081/api/question-bank')
      .then(res => setMasterBank(Array.isArray(res.data) ? res.data : []))
      .catch(() => setMasterBank(JSON.parse(localStorage.getItem('aura_math_quiz_bank')) || []));
  };

  useEffect(() => { refreshData(); }, []);

  // 🟢 2. DYNAMIC LOOKUP LOGIC: ලොග් වී සිටින ගුරුවරයාගේ විෂයන් සහ ශ්‍රේණි වෙන් කරගැනීම
  const currentTeacherCode = teachersList.find(t => t.full_name === userName)?.teacher_code || 'TC_002';
  
  // ටීචර්ට අදාළ ටයිම්ටේබල් රෙකෝඩ්ස් පමණක් පෙරා ගැනීම
  const myAssignedSlots = timetableRows.filter(t => t.teacher_code === currentTeacherCode);
  
  // ටීචර් උගන්වන විෂය කේතයන් (Distinct Subject Codes)
  const mySubjectCodes = [...new Set(myAssignedSlots.map(t => t.subject_code))];
  
  // ටීචර්ට අදාළ ඇත්තම විෂයන් ලැයිස්තුව (e.g., Mathematics විතරයි)
  const mySubjects = subjectsList.filter(sub => mySubjectCodes.includes(sub.subject_code));

  // දැනට සිලෙක්ට් කර ඇති විෂය කේතය
  const activeSubjectCode = subjectsList.find(s => s.subject_name === activeSubject)?.subject_code;

  // 🟢 ටීචර් තෝරාගත් විෂයට අදාළව ටයිම්ටේබල් එකේ ඇති ශ්‍රේණි පමණක් වෙන් කරගැනීම (e.g., Grade 6, 7, 8)
  const myAvailableGrades = [...new Set(
    myAssignedSlots.filter(t => t.subject_code === activeSubjectCode).map(t => t.grade)
  )];

  // ඩිෆෝල්ට් සිලෙක්ෂන්ස් ඔටෝම සකස් කිරීම
  useEffect(() => {
    if (mySubjects.length > 0 && !activeSubject) {
      setActiveSubject(mySubjects[0].subject_name);
    }
  }, [subjectsList, timetableRows]);

  useEffect(() => {
    if (myAvailableGrades.length > 0 && !formPaperGrade) {
      setFormPaperGrade(myAvailableGrades[0]);
    }
  }, [activeSubject, timetableRows]);

  // LocalStorage backups
  const saveQuizzesToStorage = (newQuizzes) => { setQuizzes(newQuizzes); localStorage.setItem('aura_math_quizzes', JSON.stringify(newQuizzes)); };
  const saveBankToStorage = (newBank) => { setMasterBank(newBank); localStorage.setItem('aura_math_quiz_bank', JSON.stringify(newBank)); };

  // 1. New Paper Title සාදා ඩේටාබේස් එකට යැවීම
  const handleCreatePaper = (e) => {
    e.preventDefault();
    const payload = { title: quizTitle, grade: formPaperGrade, subject: activeSubject, teacher_name: userName, is_enabled: 0 };
    
    axiosInstance.post('http://localhost:8081/api/add-quiz', payload)
      .then(() => refreshData())
      .catch(() => {
        const newQuiz = { id: Date.now(), title: quizTitle, grade: formPaperGrade, subject_name: activeSubject, teacher_name: userName, is_enabled: false };
        saveQuizzesToStorage([...quizzes, newQuiz]);
        setSelectedQuizId(newQuiz.id.toString());
        alert(`✅ Quiz Paper "${quizTitle}" Created for ${activeSubject} (${formPaperGrade})!`);
        setQuizTitle('');
      });
  };

  // 2. Toggle Quiz Active State
  const handleToggleEnable = (quiz) => {
    const updatedStatus = quiz.is_enabled === 1 || quiz.is_enabled === true ? 0 : 1;
    axiosInstance.put(`http://localhost:8081/api/toggle-quiz/${quiz.id}`, { ...quiz, is_enabled: updatedStatus })
      .then(() => refreshData())
      .catch(() => {
        const updated = quizzes.map(qz => qz.id === quiz.id ? { ...qz, is_enabled: !isEnabled(qz) } : qz);
        saveQuizzesToStorage(updated);
        alert(`✅ Quiz visibility updated!`);
      });
  };

  const isEnabled = (quiz) => quiz.is_enabled === 1 || quiz.is_enabled === true;

  // 3. Save Question Content
  const handleSaveQuestion = (e) => {
    e.preventDefault();
    const payload = { quiz_id: selectedQuizId ? parseInt(selectedQuizId) : 0, question_text: qText, marks: qMarks, option_a: optA, option_b: optB, option_c: optC, option_d: optD, correct_option: correctOpt };

    if (editingId) {
      axiosInstance.put(`http://localhost:8081/api/edit-question/${editingId}`, payload)
        .then(() => { setEditingId(null); clearForm(); refreshData(); })
        .catch(() => {
          const updated = masterBank.map(q => q.id === editingId ? { ...q, ...payload } : q);
          saveBankToStorage(updated); setEditingId(null); clearForm();
          alert("✅ Question Content Updated!");
        });
    } else {
      axiosInstance.post('http://localhost:8081/api/add-question', payload)
        .then(() => { clearForm(); refreshData(); })
        .catch(() => {
          saveBankToStorage([{ id: Date.now(), ...payload }, ...masterBank]);
          clearForm(); alert("✅ New MCQ Question added to Repository!");
        });
    }
  };

  const handleQuickLink = (question) => {
    if (!selectedQuizId) { alert("⚠️ Please select a target Quiz Paper first!"); return; }
    const updated = masterBank.map(q => q.id === question.id ? { ...q, quiz_id: parseInt(selectedQuizId) } : q);
    saveBankToStorage(updated);
    alert("➕ Question linked to chosen paper blueprint!");
  };

  const handleDeleteQuestion = (id) => {
    if (window.confirm("Delete permanently?")) {
      const updated = masterBank.filter(q => q.id !== id);
      saveBankToStorage(updated);
    }
  };

  const handleUnlinkQuestion = (question) => {
    const updated = masterBank.map(q => q.id === question.id ? { ...q, quiz_id: 0 } : q);
    saveBankToStorage(updated);
  };

  const clearForm = () => { setQText(''); setOptA(''); setOptB(''); setOptC(''); setOptD(''); setCorrectOpt('A'); };
  const handleStartEdit = (q) => { setEditingId(q.id); setQText(q.question_text); setOptA(q.option_a); setOptB(q.option_b); setOptC(q.option_c); setOptD(q.option_d); setCorrectOpt(q.correct_option); setQMarks(q.marks); };

  const filteredQuizzes = quizzes.filter(q => q.subject_name === activeSubject);
  const activePaperQuestions = masterBank.filter(q => q.quiz_id === parseInt(selectedQuizId));
  const activeQuizDetails = quizzes.find(qz => qz.id === parseInt(selectedQuizId));

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      
      {/* 🟢 TOP GLOBAL SUBJECT DROPDOWN (ඩේටාබේස් එකෙන්ම පමණක් ෆිල්ටර් වේ) */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f0fdf4', padding: '15px 20px', borderRadius: '12px', border: '1px solid #bbf7d0' }}>
        <div>
          <h2 style={{ color: '#165b33', margin: 0 }}>📝 Assigned Subject Matrix Portal</h2>
          <p style={{ color: '#16a34a', fontSize: '13px', margin: '3px 0 0 0' }}>ගුරු භවතාට අදාළ විෂයයන් සහ පන්ති කාලසටහන් දත්ත (Timetable) අනුව ස්වයංක්‍රීයව පාලනය වේ.</p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{ fontSize: '14px', fontWeight: 'bold', color: '#1e293b' }}>Active Teaching Subject:</span>
          <select 
            value={activeSubject} 
            onChange={e => { setActiveSubject(e.target.value); setSelectedQuizId(''); setFormPaperGrade(''); }} 
            style={{ padding: '10px 16px', borderRadius: '8px', border: '2px solid #16a34a', fontWeight: 'bold', color: '#165b33', backgroundColor: 'white', outline: 'none', cursor: 'pointer' }}
          >
            {mySubjects.length > 0 ? (
              mySubjects.map(sub => <option key={sub.id} value={sub.subject_name}>{sub.subject_name}</option>)
            ) : (
              <option value="Mathematics">Mathematics</option>
            )}
          </select>
        </div>
      </div>

      {/* STEP 1 & 2 TOP CONTROL GRID */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
        
        {/* STEP 1 (ශ්‍රේණි ටික නූලටම ෆිල්ටර් වේ) */}
        <div style={styles.card('#15803d')}>
          <h4 style={styles.stepTitle('#15803d')}>Step 1: Create a New Quiz Paper ({activeSubject})</h4>
          <form onSubmit={handleCreatePaper} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <input type="text" placeholder="e.g., 1 වාර ඇගයීම් පරීක්ෂණය" value={quizTitle} onChange={e => setQuizTitle(e.target.value)} required style={styles.fullInput} />
            
            {/* 🟢 DYNAMIC DROPDOWN: බුද්ධිකා ටීචර්ට Grade 6, 7, 8 විතරක්ම පෙන්වයි */}
            <select value={formPaperGrade} onChange={e => setFormPaperGrade(e.target.value)} style={styles.fullInput} required>
              {myAvailableGrades.map(g => (
                <option key={g} value={g}>{g}</option>
              ))}
              {myAvailableGrades.length === 0 && <option value="Grade 8">Grade 8</option>}
            </select>
            
            <button type="submit" style={{ ...styles.btn, backgroundColor: '#15803d', width: '100%' }}>Create Paper Schema</button>
          </form>
        </div>

        {/* STEP 2 */}
        <div style={styles.card('#2563eb')}>
          <h4 style={styles.stepTitle('#2563eb')}>Step 2: Target Exam Paper Selection</h4>
          <select value={selectedQuizId} onChange={e => setSelectedQuizId(e.target.value)} style={styles.fullInput}>
            <option value="">-- Choose Target Exam Paper --</option>
            {filteredQuizzes.map(q => (
              <option key={q.id} value={q.id}>{q.title} ({q.grade})</option>
            ))}
          </select>
        </div>
      </div>

      {/* MAIN WORKSPACE CONTENT */}
      <div style={{ display: 'grid', gridTemplateColumns: '1.1fr 1.3fr', gap: '25px', alignItems: 'start' }}>
        
        {/* LEFT WORKSPACE: MASTER FORM */}
        <div style={styles.card('#475569')}>
          <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b' }}>➕ Add Custom Question to Bank</h3>
          <form onSubmit={handleSaveQuestion} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div>
              <label style={styles.label}>ප්‍රශ්න විස්තරය</label>
              <textarea placeholder="ගණිත ගැටලුව මෙතන ලියන්න..." value={qText} onChange={e => setQText(e.target.value)} required style={{ ...styles.fullInput, height: '60px', resize: 'none' }} />
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'A'} onChange={() => setCorrectOpt('A')} name="ans" /><input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'B'} onChange={() => setCorrectOpt('B')} name="ans" /><input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'C'} onChange={() => setCorrectOpt('C')} name="ans" /><input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'D'} onChange={() => setCorrectOpt('D')} name="ans" /><input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required style={styles.fullInput} /></div>
            </div>
            <button type="submit" style={{ ...styles.btn, backgroundColor: '#475569', padding: '11px' }}>Save Inside Repository Bank 💾</button>
          </form>
        </div>

        {/* RIGHT WORKSPACE: REPOSITORY SUMMARY */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div style={styles.card('#6b21a8')}>
            <h3 style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#1e293b' }}>📚 Central Question Bank Repository</h3>
            <p style={{ margin: '0 0 15px 0', fontSize: '12px', color: '#64748b' }}>ඩේටාබේස් එකෙන් ලෝඩ් වන ප්‍රශ්න එකතුව.</p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '180px', overflowY: 'auto', paddingRight: '5px' }}>
              {masterBank.length > 0 ? (
                masterBank.map((q, idx) => {
                  const isLinked = q.quiz_id > 0;
                  return (
                    <div key={q.id || idx} style={{ backgroundColor: '#f8fafc', padding: '15px', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', marginBottom: '6px' }}>
                        <span style={{ color: '#64748b', fontWeight: 'bold' }}>Question Ref #{idx + 1}</span>
                        <span style={{ color: window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId) ? '#16a34a' : isLinked ? '#2563eb' : '#ea580c', fontWeight: 'bold' }}>
                          {window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId) ? '✓ Added to Current Paper' : isLinked ? 'Linked to Other Paper' : '📌 Available in Bank'}
                        </span>
                      </div>
                      <h5 style={{ margin: '0 0 10px 0', fontSize: '13.5px', color: '#1e293b', lineHeight: '1.4' }}>{q.question_text}</h5>
                      <div style={{ display: 'flex', gap: '10px' }}>
                        <button onClick={() => handleStartEdit(q)} style={styles.miniBtn}>✏️ Edit</button>
                        <button onClick={() => handleDeleteQuestion(q.id)} style={{ ...styles.miniBtn, color: '#b91c1c', backgroundColor: '#fee2e2' }}>🗑️ Delete</button>
                        <button onClick={() => handleQuickLink(q)} disabled={window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId)} style={{ ...styles.miniBtn, backgroundColor: window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId) ? '#cbd5e1' : '#16a34a', color: 'white', border: 'none', marginLeft: 'auto' }}>
                          {window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId) ? 'Added ✓' : '➕ Link Paper'}
                        </button>
                      </div>
                    </div>
                  );
                })
              ) : (
                <p style={{ color: '#94a3b8', textAlign: 'center', fontSize: '13px', fontStyle: 'italic' }}>📭 ප්‍රශ්න බැංකුව හිස්ව පවතී.</p>
              )}
            </div>
          </div>

          <div style={styles.card('#e11d48')}>
            <h3 style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#1e293b' }}>📂 Created Quiz Papers ({activeSubject})</h3>
            <p style={{ margin: '0 0 15px 0', fontSize: '12px', color: '#64748b' }}>සාදන ලද ප්‍රශ්න පත්‍රවල දෘශ්‍යතාව පාලනය කරන්න (Visibility Control).</p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', maxHeight: '180px', overflowY: 'auto', paddingRight: '5px' }}>
              {filteredQuizzes.length > 0 ? (
                filteredQuizzes.map((qz, idx) => {
                  const activeStatus = isEnabled(qz);
                  return (
                    <div key={qz.id || idx} style={{ backgroundColor: '#f8fafc', padding: '12px', borderRadius: '10px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div>
                        <h5 style={{ margin: '0 0 4px 0', fontSize: '13.5px', color: '#1e293b', fontWeight: '600' }}>{qz.title}</h5>
                        <span style={{ fontSize: '11px', backgroundColor: '#e2e8f0', padding: '2px 6px', borderRadius: '4px', fontWeight: 'bold', color: '#475569' }}>{qz.grade}</span>
                      </div>
                      <button onClick={() => handleToggleEnable(qz)} style={{ padding: '6px 14px', borderRadius: '8px', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '11.5px', backgroundColor: activeStatus ? '#16a34a' : '#dc2626', color: 'white' }}>
                        {activeStatus ? '🟢 Enabled' : '🔴 Disabled'}
                      </button>
                    </div>
                  );
                })
              ) : (
                <p style={{ color: '#94a3b8', textAlign: 'center', fontSize: '13px', fontStyle: 'italic' }}>📭 ප්‍රශ්න පත්‍ර කිසිවක් සාදා නැත.</p>
              )}
            </div>
          </div>
        </div>

      </div>

      {/* BOTTOM DISPLAY: EXAM PREVIEW SHEET */}
      <div style={{ marginTop: '5px' }}>
        <h3 style={{ color: '#1e293b', marginBottom: '12px' }}>📝 Live MCQ Examination Paper Layout Preview</h3>
        <div style={{ backgroundColor: 'white', padding: '40px', borderRadius: '16px', border: '1px solid #cbd5e1', boxShadow: '0 4px 20px rgba(0,0,0,0.01)' }}>
          <div style={{ borderBottom: '3px double #334155', paddingBottom: '15px', marginBottom: '30px', textAlign: 'center' }}>
            <span style={{ fontSize: '12px', fontWeight: 'bold', color: '#2563eb', letterSpacing: '1.5px', backgroundColor: '#dbeafe', padding: '3px 12px', borderRadius: '10px' }}>AURA EDUCATION SYSTEM - OFFICIAL ASSESSMENT SHEET</span>
            <h3 style={{ margin: '10px 0 5px 0', fontSize: '20px', color: '#1e293b' }}>{selectedQuizId && activeQuizDetails ? activeQuizDetails.title : "Active Examination"}</h3>
            <div style={{ display: 'flex', justifyContent: 'center', gap: '20px', fontSize: '13px', color: '#64748b', fontWeight: '500', marginTop: '5px' }}>
              <span>Subject: {activeSubject}</span>
              <span>Target Structure: {selectedQuizId && activeQuizDetails ? activeQuizDetails.grade : formPaperGrade}</span>
              <span>Total Questions: {activePaperQuestions.length}</span>
            </div>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>
            {activePaperQuestions.length > 0 ? (
              activePaperQuestions.map((q, idx) => (
                <div key={q.id || idx} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                  <div style={{ display: 'flex', gap: '10px', fontSize: '15px', fontWeight: '600', color: '#1e293b' }}>
                    <span>({idx + 1})</span>
                    <p style={{ margin: 0, flex: 1, lineHeight: '1.4' }}>{q.question_text}</p>
                    <button onClick={() => handleUnlinkQuestion(q)} style={{ border: 'none', background: 'none', color: '#ef4444', fontSize: '11px', cursor: 'pointer', fontWeight: 'bold' }}>[❌ Remove Paper]</button>
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', paddingLeft: '30px', marginTop: '4px' }}>
                    <div style={styles.previewOpt}><input type="radio" disabled checked={q.correct_option === 'A'} /> <span>(A) {q.option_a}</span></div>
                    <div style={styles.previewOpt}><input type="radio" disabled checked={q.correct_option === 'B'} /> <span>(B) {q.option_b}</span></div>
                    <div style={styles.previewOpt}><input type="radio" disabled checked={q.correct_option === 'C'} /> <span>(C) {q.option_c}</span></div>
                    <div style={styles.previewOpt}><input type="radio" disabled checked={q.correct_option === 'D'} /> <span>(D) {q.option_d}</span></div>
                  </div>
                  <div style={{ paddingLeft: '30px', fontSize: '12px', color: '#16a34a', fontWeight: 'bold', marginTop: '4px' }}>🔑 Correct System Answer Matrix Key: Option ({q.correct_option})</div>
                </div>
              ))
            ) : (
              <div style={{ textAlign: 'center', padding: '40px', color: '#94a3b8', fontStyle: 'italic' }}>📭 මෙම ප්‍රශ්න පත්‍රය දැනට හිස්ව පවතී.</div>
            )}
          </div>
        </div>
      </div>

    </div>
  );
}

const styles = {
  card: (color) => ({ backgroundColor: 'white', padding: '24px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column' }),
  stepTitle: (color) => ({ margin: '0 0 12px 0', fontSize: '14.5px', color: color, fontWeight: 'bold' }),
  fullInput: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', fontSize: '13.5px', boxSizing: 'border-box' },
  btn: { color: 'white', border: 'none', padding: '11px 20px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13.5px' },
  label: { display: 'block', fontSize: '12px', fontWeight: 'bold', color: '#475569', marginBottom: '6px' },
  optRow: { display: 'flex', alignItems: 'center', gap: '10px', width: '100%' },
  miniBtn: { padding: '6px 12px', border: '1px solid #cbd5e1', backgroundColor: 'white', borderRadius: '6px', cursor: 'pointer', fontSize: '11.5px', fontWeight: 'bold', color: '#334155' },
  previewOpt: { display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: '#334155', fontWeight: '500' }
};
